using Clary.Api.Identity;
using Npgsql;
namespace Clary.Api;
public record TicketAttachment(Guid Id,string Filename,long Size,string UploaderName,DateTime CreatedAt,bool CanRemove);
public record TicketAttachmentFile(string Filename,byte[] Content);
public sealed partial class TicketRepository {
 public async Task<IReadOnlyList<TicketAttachment>> AttachmentsAsync(CompanyContext c,Guid ticket,CancellationToken ct){await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);_ = await Get(conn,tx,c,ticket,ct)??throw new InventoryMissing();await using var q=Q(conn,tx,c,"SELECT id,filename,octet_length(content),uploader_name,created_at,uploader_user_id FROM ticket_attachments WHERE company_id=@company AND ticket_id=@ticket ORDER BY created_at,id");q.Parameters.AddWithValue("ticket",ticket);var rows=new List<TicketAttachment>();await using var reader=await q.ExecuteReaderAsync(ct);while(await reader.ReadAsync(ct))rows.Add(new(reader.GetGuid(0),reader.GetString(1),reader.GetInt32(2),reader.GetString(3),reader.GetDateTime(4),reader.GetGuid(5)==c.UserId||TicketAccess.Manager(c)));return rows;}
 public async Task<TicketAttachment> AddAttachmentAsync(CompanyContext c,Guid ticket,string filename,byte[] content,CancellationToken ct){filename=Text(filename.Replace('\\','/').Split('/').Last(),200,true);if(content.Length is <1 or >10485760)throw new ArgumentException("Choose a file up to 10 MB.");await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);await Lock(conn,tx,c,ticket,ct);var before=await Get(conn,tx,c,ticket,ct)??throw new InventoryMissing();if(!before.AllowedActions.Contains("comment"))throw new CompanyDenied();await using(var count=Q(conn,tx,c,"SELECT count(*) FROM ticket_attachments WHERE company_id=@company AND ticket_id=@ticket")){count.Parameters.AddWithValue("ticket",ticket);if((long)(await count.ExecuteScalarAsync(ct))!>=20)throw new ArgumentException("A ticket can have up to 20 attachments.");}var id=Guid.NewGuid();var actor=await Actor(conn,tx,c,ct);await using var q=Q(conn,tx,c,"INSERT INTO ticket_attachments(company_id,ticket_id,id,filename,content,uploader_user_id,uploader_name) VALUES(@company,@ticket,@id,@filename,@content,@user,@actor) RETURNING created_at");q.Parameters.AddWithValue("ticket",ticket);q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("filename",filename);q.Parameters.AddWithValue("content",content);q.Parameters.AddWithValue("actor",actor);var at=(DateTime)(await q.ExecuteScalarAsync(ct))!;await Activity(conn,tx,c,ticket,"Attachment added",filename,ct);await tx.CommitAsync(ct);return new(id,filename,content.Length,actor,at,true);}
 public async Task<TicketAttachmentFile> OpenAttachmentAsync(CompanyContext c,Guid ticket,Guid id,CancellationToken ct){await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);_ = await Get(conn,tx,c,ticket,ct)??throw new InventoryMissing();await using var q=Q(conn,tx,c,"SELECT filename,content FROM ticket_attachments WHERE company_id=@company AND ticket_id=@ticket AND id=@id");q.Parameters.AddWithValue("ticket",ticket);q.Parameters.AddWithValue("id",id);await using var reader=await q.ExecuteReaderAsync(ct);if(!await reader.ReadAsync(ct))throw new InventoryMissing();return new(reader.GetString(0),reader.GetFieldValue<byte[]>(1));}
 public async Task<object> RemoveAttachmentAsync(CompanyContext c,Guid ticket,Guid id,CancellationToken ct){await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);await Lock(conn,tx,c,ticket,ct);_ = await Get(conn,tx,c,ticket,ct)??throw new InventoryMissing();await using var q=Q(conn,tx,c,"DELETE FROM ticket_attachments WHERE company_id=@company AND ticket_id=@ticket AND id=@id AND (uploader_user_id=@user OR @manager) RETURNING filename");q.Parameters.AddWithValue("ticket",ticket);q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("manager",TicketAccess.Manager(c));var filename=await q.ExecuteScalarAsync(ct) as string??throw new InventoryMissing();await Activity(conn,tx,c,ticket,"Attachment removed",filename,ct);await tx.CommitAsync(ct);return new{deleted=true};}
}
